\"\"\"Send private text prompts to the OpenAI Responses API.

Standard library only. Prompt text is not written to disk. Requests set
"'``store`` to false so the API does not retain the response for later retrieval.
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Mapping

DEFAULT_API_URL = "https://api.openai.com/v1/responses"
DEFAULT_TIMEOUT_SECONDS = 60.0


class OpenAIResponseError(RuntimeError):
    """Raised when the Responses API rejects a request or returns no text."""

    def __init__(self, message: str, status: int | None = None) -> None:
        super().__init__(message)
        self.status = status


def send_private_prompt(
    prompt: str,
    *,
    model: str | None = None,
    api_key: str | None = None,
    instructions: str | None = None,
    timeout: float = DEFAULT_TIMEOUT_SECONDS,
    base_url: str | None = None,
    extra_body: Mapping[str, Any] | None = None,
) -> str:
    """Send a text prompt and return the assistant text.

    ``store`` is always false. The prompt is not logged or saved by this module.
    The API key is read from ``api_key`` or the ``OPENAI_API_KEY`` environment
    variable and is not included in raised errors.
    """
    text = _require_text(prompt, "prompt")
    chosen_model = model or os.environ.get("OPENAI_MODEL")
    if not chosen_model or not chosen_model.strip():
        raise OpenAIResponseError(
            "model is required; pass model or set OPENAI_MODEL"
        )

    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key or not key.strip():
        raise OpenAIResponseError(
            "API key is required; pass api_key or set OPENAI_API_KEY"
        )

    body: dict[str, Any] = {
        "model": chosen_model.strip(),
        "input": text,
        "store": False,
    }
    if instructions is not None:
        body["instructions"] = _require_text(instructions, "instructions")
    if extra_body:
        overlap = set(extra_body).intersection(body)
        if overlap:
            names = ", ".join(sorted(overlap))
            raise OpenAIResponseError(f"extra_body cannot override: {names}")
        body.update(extra_body)
    body["store"] = False

    url = (base_url or os.environ.get("OPENAI_BASE_URL") or DEFAULT_API_URL).strip()
    payload = json.dumps(body).encode("utf-8")
    request = urllib.request.Request(
        url,
        data=payload,
        headers={
            "Authorization": f"Bearer {key.strip()}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read()
    except urllib.error.HTTPError as exc:
        detail = _safe_error_detail(exc)
        raise OpenAIResponseError(
            f"OpenAI Responses API error ({exc.code}): {detail}",
            status=exc.code,
        ) from None
    except urllib.error.URLError as exc:
        reason = getattr(exc, "reason", exc)
        raise OpenAIResponseError(f"OpenAI Responses API request failed: {reason}") from None

    try:
        parsed = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise OpenAIResponseError("OpenAI Responses API returned invalid JSON") from None

    if not isinstance(parsed, dict):
        raise OpenAIResponseError("OpenAI Responses API returned an unexpected payload")

    status = parsed.get("status")
    if status not in (None, "completed"):
        raise OpenAIResponseError(
            f"OpenAI Responses API status was {status}",
            status=None,
        )

    output = _extract_output_text(parsed)
    if not output:
        raise OpenAIResponseError("OpenAI Responses API returned no text")
    return output


def _require_text(value: str, name: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise OpenAIResponseError(f"{name} must be a non-empty string")
    return value


def _safe_error_detail(exc: urllib.error.HTTPError) -> str:
    try:
        raw = exc.read()
    except Exception:
        return exc.reason if isinstance(exc.reason, str) else "request failed"
    try:
        parsed = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return exc.reason if isinstance(exc.reason, str) else "request failed"
    if isinstance(parsed, dict):
        error = parsed.get("error")
        if isinstance(error, dict):
            message = error.get("message")
            if isinstance(message, str) and message.strip():
                return message.strip()
        message = parsed.get("message")
        if isinstance(message, str) and message.strip():
            return message.strip()
    return exc.reason if isinstance(exc.reason, str) else "request failed"


def _extract_output_text(payload: Mapping[str, Any]) -> str:
    direct = payload.get("output_text")
    if isinstance(direct, str) and direct:
        return direct

    chunks: list[str] = []
    output = payload.get("output")
    if not isinstance(output, list):
        return ""
    for item in output:
        if not isinstance(item, dict):
            continue
        if item.get("type") == "output_text" and isinstance(item.get("text"), str):
            chunks.append(item["text"])
            continue
        content = item.get("content")
        if not isinstance(content, list):
            continue
        for part in content:
            if not isinstance(part, dict):
                continue
            if part.get("type") in {"output_text", "text"} and isinstance(part.get("text"), str):
                chunks.append(part["text"])
    return "".join(chunks)


def main() -> int:
    """Read a prompt from stdin so it is not placed on the command line."""
    prompt = sys.stdin.read()
    try:
        sys.stdout.write(send_private_prompt(prompt))
        if not prompt.endswith("'"\\n\"):
            sys.stdout.write(\"\\n\")
    except OpenAIResponseError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
